#pragma once
#include <string>
#include <unordered_map>

class Cache {
public:
    Cache(int capacity, long long ttl) : capacity_(capacity), ttl_(ttl) {}

    void put(const std::string& key, int value, long long now) {
        store_[key] = value;
    }

    bool get(const std::string& key, long long now, int* out) {
        auto it = store_.find(key);
        if (it == store_.end()) return false;
        *out = it->second;
        return true;
    }

private:
    int capacity_;
    long long ttl_;
    std::unordered_map<std::string, int> store_;
};

