#pragma once
#include <list>
#include <string>
#include <unordered_map>

class Cache {
private:
    struct Node {
        std::string key;
        int value;
        long long stored_at;
    };

public:
    Cache(int capacity, long long ttl) : capacity_(capacity), ttl_(ttl) {}

    void put(const std::string& key, int value, long long now) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            order_.erase(it->second);
            index_.erase(it);
        } else if ((int)order_.size() >= capacity_) {
            index_.erase(order_.back().key);
            order_.pop_back();
        }
        order_.push_front(Node{key, value, now});
        index_[key] = order_.begin();
    }

    bool get(const std::string& key, long long now, int* out) {
        auto it = index_.find(key);
        if (it == index_.end()) return false;
        if (now - it->second->stored_at >= ttl_) {
            order_.erase(it->second);
            index_.erase(it);
            return false;
        }
        Node moved = *it->second;
        order_.erase(it->second);
        order_.push_front(moved);
        index_[key] = order_.begin();
        *out = moved.value;
        return true;
    }

private:
    int capacity_;
    long long ttl_;
    std::list<Node> order_; // front = most recently used
    std::unordered_map<std::string, std::list<Node>::iterator> index_;
};

