test_setup_files.test_cache.cpp:
#include "cache.h"
#include <cassert>
#include <iostream>

int main() {
    {
        Cache c(2, 1000);
        c.put("a", 1, 0);
        c.put("b", 2, 1);
        int out;
        c.get("a", 2, &out);
        c.put("c", 3, 3);
        assert(c.get("a", 4, &out) && out == 1);
        assert(!c.get("b", 4, &out));
        assert(c.get("c", 4, &out) && out == 3);
    }
    {
        Cache c(2, 1000);
        c.put("a", 1, 0);
        c.put("b", 2, 1);
        int out;
        c.get("a", 2, &out);
        c.get("b", 3, &out);
        c.put("c", 3, 4);
        assert(!c.get("a", 5, &out));
        assert(c.get("b", 5, &out) && out == 2);
    }
    {
        Cache c(5, 10);
        c.put("a", 1, 0);
        int out;
        assert(c.get("a", 9, &out) && out == 1);
        assert(!c.get("a", 10, &out));
    }
    std::cout << "PASS" << std::endl;
    return 0;
}
